const POOL_SIZE = 64 * 1024;
const BLOCK_SIZE = 64;
const pool = new ArrayBuffer(POOL_SIZE);
const nextFree = new Int32Array(pool);
let head = 0;
function init_pool(){ const blocks = POOL_SIZE / BLOCK_SIZE; for(let i=0;i<blocks-1;i++){ nextFree[i] = i+1; } nextFree[blocks-1] = -1; head = 0; }
function my_malloc(){ if(head === -1) return null; const idx = head; head = nextFree[idx]; return new DataView(pool, idx*BLOCK_SIZE, BLOCK_SIZE); }
